import React, { useEffect, useState } from 'react';
import { Pie } from 'react-chartjs-2';
import { deleteAdminUser, exportCsv, getAdminStats, getAdminUsers } from '../services/api';

export default function AdminDashboard() {
  const [stats, setStats] = useState(null);
  const [users, setUsers] = useState([]);

  const load = () => {
    getAdminStats().then((r) => setStats(r.data));
    getAdminUsers().then((r) => setUsers(r.data.users || []));
  };

  useEffect(() => { load(); }, []);

  const handleExport = async () => {
    const res = await exportCsv();
    const url = window.URL.createObjectURL(new Blob([res.data]));
    const a = document.createElement('a');
    a.href = url;
    a.download = 'assessments_export.csv';
    a.click();
  };

  const handleDelete = async (uid) => {
    if (window.confirm('Delete this user?')) {
      await deleteAdminUser(uid);
      load();
    }
  };

  if (!stats) return <div><h2>Admin Dashboard</h2><p>Loading...</p></div>;

  const pieData = {
    labels: Object.keys(stats.riskDistribution || {}),
    datasets: [{
      data: Object.values(stats.riskDistribution || {}),
      backgroundColor: ['#22c55e', '#eab308', '#ef4444'],
    }],
  };

  return (
    <div>
      <h2 className="mb-4">Admin Dashboard</h2>
      <div className="row g-3 mb-4">
        <div className="col-md-3"><div className="card card-mw p-3"><h6>Total Users</h6><h3>{stats.totalUsers}</h3></div></div>
        <div className="col-md-3"><div className="card card-mw p-3"><h6>Total Assessments</h6><h3>{stats.totalAssessments}</h3></div></div>
        <div className="col-md-3"><div className="card card-mw p-3"><h6>Avg Confidence</h6><h3>{stats.averageConfidence}%</h3></div></div>
        <div className="col-md-3">
          <div className="card card-mw p-3">
            <button className="btn btn-outline-primary btn-sm" onClick={handleExport}>Export CSV</button>
          </div>
        </div>
      </div>
      <div className="row g-4">
        <div className="col-md-5">
          <div className="card card-mw p-3">
            <h6>Risk Distribution</h6>
            <Pie data={pieData} />
          </div>
        </div>
        <div className="col-md-7">
          <div className="card card-mw p-3">
            <h6>User Management</h6>
            <table className="table table-sm">
              <thead><tr><th>Name</th><th>Email</th><th></th></tr></thead>
              <tbody>
                {users.map((u) => (
                  <tr key={u.uid}>
                    <td>{u.name}</td>
                    <td>{u.email}</td>
                    <td><button className="btn btn-sm btn-outline-danger" onClick={() => handleDelete(u.uid)}>Delete</button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}
